H.background();
const w = H.W, hh = H.H;
const n = Math.max(1, Math.round(P.n));
const p = Math.min(0.99, Math.max(0.01, P.p));
function fact(x) { let f = 1; for (let i = 2; i <= x; i++) f *= i; return f; }
function C(nn, kk) { return fact(nn) / (fact(kk) * fact(nn - kk)); }
const probs = [];
let pmax = 0;
for (let k = 0; k <= n; k++) { const pr = C(n, k) * Math.pow(p, k) * Math.pow(1 - p, n - k); probs.push(pr); if (pr > pmax) pmax = pr; }
H.text("Binomial: P(X=k) = C(n,k)·p^k·(1−p)^(n−k)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("n = " + n + " trials   p = " + p.toFixed(2) + "   mean μ = np = " + (n * p).toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });
const baseY = hh - 90, plotH = hh - 200;
const bw = Math.min(60, (w - 120) / (n + 1));
const x0 = (w - bw * (n + 1)) / 2;
const litK = Math.floor((t * 0.8) % (n + 1));
let cum = 0;
for (let k = 0; k <= n; k++) {
  const bx = x0 + k * bw, bh = (pmax > 0 ? probs[k] / pmax : 0) * plotH;
  const lit = k === litK;
  H.rect(bx + 4, baseY - bh, bw - 8, bh, { fill: lit ? H.colors.warn : H.colors.accent, stroke: H.colors.bg, width: 1, radius: 3 });
